// Prevents the AI's own TTS audio (reflected back by Exotel) from being
// mistakenly treated as caller speech and triggering a false barge-in.
const ECHO_SUPPRESS_MS = 2000;

// Discard inbound audio for this many ms after AI finishes speaking.
// Catches any trailing echo before the caller's genuine response begins.
const POST_SPEAK_COOLDOWN_MS = 800;

