// ── Echo suppression window: ignore all audio right after AI speaks ─
// The AI's own TTS audio is reflected back by Exotel as inbound audio.
// We blind ourselves for ECHO_SUPPRESS_MS after AI starts speaking to
// prevent that echo from being mistaken for caller speech (barge-in).
if (session.isSpeaking && session.speakingStartedAt !== null) {
  const elapsed = Date.now() - session.speakingStartedAt;
  if (elapsed < ECHO_SUPPRESS_MS) {
    break; // still in echo window — discard completely
  }
}

