if (!session.isSpeaking && session.speakingEndedAt !== null) {
  const elapsed = Date.now() - session.speakingEndedAt;
  if (elapsed < POST_SPEAK_COOLDOWN_MS) {
    break; // cooldown period — discard
  }
  // Cooldown expired — clear the timestamp so we stop checking
  session.speakingEndedAt = null;
}

