arguments.content:
/**
 * OpenAI Realtime API Bridge for Exotel calls
 *
 * Architecture:
 *   Exotel (PCM16 LE 8kHz) ↔ [μ-law encode/decode] ↔ OpenAI Realtime API (g711_ulaw 8kHz)
 *
 * Why this is better than the old pipeline:
 *   Old:  Buffer audio → Whisper STT (~1.5s) → GPT (~0.8s) → TTS (~0.8s) = ~4–6s latency
 *   New:  Stream to Realtime API → response streams back = ~300–500ms latency
 *
 * Audio format bridge:
 *   - Exotel sends PCM16 LE 8kHz (slin16), base64-encoded in Media events
 *   - Realtime API uses g711_ulaw (8kHz μ-law) — same sample rate, different encoding
 *   - We encode PCM16→μ-law for input, decode μ-law→PCM16 for output
 *   - No resampling needed — eliminates the main source of audio distortion
 */

import { WebSocket } from "ws";
import { log } from "./index";
import { loadCampaignData, encodeMulaw, decodeMulaw } from "./exotelStreamHandler";
import { callSidMap, phoneCallMap, normalizePhone } from "./callMap";

const REALTIME_URL =
  "wss://api.openai.com/v1/realtime?model=gpt-4o-realtime-preview-2024-12-17";

// ─── Audio conversion helpers ─────────────────────────────────────────────────

/** PCM16 LE buffer (Exotel) → μ-law buffer (Realtime API g711_ulaw) */
function pcm16ToMulaw(pcmBuf: Buffer): Buffer {
  const samples = new Int16Array(pcmBuf.buffer, pcmBuf.byteOffset, pcmBuf.byteLength / 2);
  const out = Buffer.allocUnsafe(samples.length);
  for (let i = 0; i < samples.length; i++) out[i] = encodeMulaw(samples[i]);
  return out;
}

/** μ-law buffer (Realtime API g711_ulaw) → PCM16 LE buffer (Exotel) */
function mulawToPcm16(mulawBuf: Buffer): Buffer {
  const out = Buffer.allocUnsafe(mulawBuf.length * 2);
  for (let i = 0; i < mulawBuf.length; i++) {
    out.writeInt16LE(decodeMulaw(mulawBuf[i]), i * 2);
  }
  return out;
}

// ─── Instructions builder ─────────────────────────────────────────────────────

function buildInstructions(campaign: any): string {
  const { name, goal, additionalContext, ai_generated_script, knowledge_base } = campaign;
  const isSupport = (goal ?? "").toLowerCase().includes("support");

  const parts = [
    `You are a professional AI ${isSupport ? "customer support" : "sales"} agent on a LIVE phone call.`,
    name        ? `Campaign: ${name}`                                          : "",
    goal        ? `Goal: ${goal}`                                              : "",
    additionalContext   ? `About us: ${additionalContext}`                     : "",
    ai_generated_script ? `Call script (use as a guide, not word-for-word):\n${ai_generated_script}` : "",
    knowledge_base      ? `Knowledge base:\n${String(knowledge_base).slice(0, 3000)}`                 : "",
    "",
    "RULES — follow all of these exactly:",
    "1. Start immediately with a warm, natural greeting. Introduce yourself and the campaign purpose.",
    "2. Speak in 1–2 short sentences per turn. No monologues.",
    "3. PRIORITY: If the caller asks a specific question (amenities, price, features, location), answer it COMPLETELY and DIRECTLY before asking anything else. Never dodge or deflect.",
    "4. Only ask ONE follow-up question per turn, and only after you have answered their question.",
    "5. NEVER ask a question the caller already answered earlier in the conversation.",
    "6. If audio is unclear, say \"Sorry, could you repeat that?\" — never say \"I can't hear you\".",
    "7. No bullet points, lists, or formatting — only natural spoken words.",
    "8. If asked about something not in your knowledge base, say \"Let me get back to you on that\" and move on.",
    "9. If they say they're busy, ask when would be a good time to call back.",
  ];

  return parts.filter(Boolean).join("\n");
}

// ─── Main handler ─────────────────────────────────────────────────────────────

export async function handleExotelRealtimeStream(
  exotelWs: WebSocket,
  initialCampaignId?: string
): Promise<void> {
  let streamSid    = "";
  let campaignId   = initialCampaignId;
  let openaiWs: WebSocket | null = null;
  let sessionReady = false;     // true after session.updated received
  let audioQueue: string[] = []; // base64 μ-law chunks buffered before session is ready

  log(`[realtime] session started campaignId=${campaignId ?? "none"}`, "ws");

  function safeJson(s: string): any | null {
    try { return JSON.parse(s); } catch { return null; }
  }

  // ── Build and connect the OpenAI Realtime WebSocket ──────────────────────
  function connectRealtime(instructions: string): void {
    log("[realtime] Connecting to OpenAI Realtime API…", "ws");

    const ws = new WebSocket(REALTIME_URL, {
      headers: {
        Authorization:  `Bearer ${process.env.OPENAI_API_KEY}`,
        "OpenAI-Beta":  "realtime=v1",
      },
    });

    openaiWs = ws;

    ws.on("open", () => {
      log("[realtime] OpenAI Realtime connected — sending session.update", "ws");

      ws.send(JSON.stringify({
        type: "session.update",
        session: {
          modalities:                   ["text", "audio"],
          instructions,
          voice:                        "nova",
          input_audio_format:           "g711_ulaw",
          output_audio_format:          "g711_ulaw",
          input_audio_transcription:    { model: "whisper-1" },
          turn_detection: {
            type:                "server_vad",
            threshold:           0.5,     // VAD sensitivity (0–1)
            prefix_padding_ms:   300,     // audio before detected speech to include
            silence_duration_ms: 600,     // silence after speech before processing
          },
        },
      }));
    });

    ws.on("message", (data: Buffer) => {
      const msg = safeJson(data.toString());
      if (!msg) return;

      switch (msg.type) {

        case "session.created":
          log("[realtime] session.created", "ws");
          break;

        case "session.updated":
          log("[realtime] session.updated — session ready", "ws");
          sessionReady = true;

          // Flush any audio that arrived before session was ready
          if (audioQueue.length > 0) {
            log(`[realtime] flushing ${audioQueue.length} queued audio chunks`, "ws");
            for (const chunk of audioQueue) {
              ws.send(JSON.stringify({ type: "input_audio_buffer.append", audio: chunk }));
            }
            audioQueue = [];
          }

          // Trigger the AI greeting immediately
          ws.send(JSON.stringify({ type: "response.create" }));
          break;

        case "response.audio.delta":
          // AI is speaking — forward audio to Exotel
          if (msg.delta && exotelWs.readyState === WebSocket.OPEN) {
            // Realtime sends g711_ulaw; Exotel expects PCM16 LE
            const mulawBuf = Buffer.from(msg.delta, "base64");
            const pcm16Buf = mulawToPcm16(mulawBuf);
            exotelWs.send(JSON.stringify({
              event:      "media",
              stream_sid: streamSid,
              media:      { payload: pcm16Buf.toString("base64") },
            }));
          }
          break;

        case "response.audio.done":
          log("[realtime] AI audio finished", "ws");
          break;

        case "input_audio_buffer.speech_started":
          // Caller started speaking — clear Exotel's playback buffer (barge-in)
          log("[realtime] ▶ Caller speech detected — clearing Exotel audio", "ws");
          if (exotelWs.readyState === WebSocket.OPEN) {
            exotelWs.send(JSON.stringify({ event: "clear", stream_sid: streamSid }));
          }
          break;

        case "input_audio_buffer.speech_stopped":
          log("[realtime] ▶ Caller speech ended — processing…", "ws");
          break;

        case "response.audio_transcript.done":
          log(`[realtime] AI said: "${msg.transcript}"`, "ws");
          break;

        case "conversation.item.input_audio_transcription.completed":
          log(`[realtime] Caller said: "${msg.transcript}"`, "ws");
          break;

        case "response.done":
          log("[realtime] response.done", "ws");
          break;

        case "error":
          log(`[realtime] OpenAI error: ${JSON.stringify(msg.error)}`, "ws");
          break;

        default:
          // Uncomment for verbose debugging:
          // log(`[realtime] unhandled: ${msg.type}`, "ws");
      }
    });

    ws.on("close", (code) => {
      log(`[realtime] OpenAI Realtime closed (code=${code})`, "ws");
      sessionReady = false;
      openaiWs     = null;
    });

    ws.on("error", (err) => {
      log(`[realtime] OpenAI Realtime error: ${err.message}`, "ws");
    });
  }

  // ── Handle incoming Exotel WebSocket events ───────────────────────────────
  exotelWs.on("message", async (raw: Buffer | string) => {
    const rawText = Buffer.isBuffer(raw) ? raw.toString("utf8") : String(raw);
    const payload = safeJson(rawText);
    if (!payload) return;

    const eventName = (
      payload?.event ?? payload?.type ?? payload?.message_type ?? ""
    ).toString().toLowerCase();

    if (eventName !== "media") {
      log(`[realtime:exotel] event="${eventName}"`, "ws");
    }

    try {
      switch (eventName) {

        case "connected":
          log("[realtime:exotel] Exotel connected", "ws");
          break;

        case "start": {
          // Extract streamSid
          streamSid =
            payload?.streamSid        ?? payload?.stream_sid        ??
            payload?.start?.streamSid ?? payload?.start?.stream_sid ?? "";

          // Resolve campaignId (3-layer fallback: payload → CallSid → phone number)
          const fromPayload =
            payload?.campaignId                              ??
            payload?.start?.campaignId                      ??
            payload?.start?.custom_parameters?.campaignId   ??
            payload?.params?.campaignId;

          if (fromPayload)  campaignId = fromPayload;

          if (!campaignId) {
            const callSid =
              payload?.start?.call_sid ?? payload?.start?.CallSid ??
              payload?.call_sid        ?? "";
            if (callSid) {
              const mapped = callSidMap.get(callSid);
              if (mapped) { campaignId = mapped; callSidMap.delete(callSid); }
            }
          }

          if (!campaignId) {
            const fromRaw =
              payload?.start?.from ?? payload?.start?.From ??
              payload?.from        ?? payload?.From        ?? "";
            if (fromRaw) {
              const key    = normalizePhone(fromRaw);
              const mapped = phoneCallMap.get(key);
              if (mapped) { campaignId = mapped; phoneCallMap.delete(key); }
            }
          }

          log(`[realtime:exotel] streamSid=${streamSid} campaignId=${campaignId ?? "none (fallback)"}`, "ws");

          // Load campaign data and launch OpenAI connection
          const campaignData = await loadCampaignData(campaignId);
          const instructions = buildInstructions(campaignData);
          connectRealtime(instructions);
          break;
        }

        case "media": {
          // Extract base64 audio payload
          const encoded =
            payload?.media?.payload ?? payload?.media?.data ??
            payload?.payload        ?? payload?.data        ?? null;
          if (!encoded) break;

          // Only process inbound (caller) audio
          const track = payload?.media?.track ?? "inbound";
          if (track !== "inbound") break;

          // Exotel sends PCM16 LE 8kHz → encode to μ-law for Realtime API
          let mulawB64: string;
          try {
            const pcmBuf  = Buffer.from(encoded, "base64");
            const mulawBuf = pcm16ToMulaw(pcmBuf);
            mulawB64 = mulawBuf.toString("base64");
          } catch {
            break;
          }

          if (!openaiWs || openaiWs.readyState !== WebSocket.OPEN) break;

          if (!sessionReady) {
            // Queue until session is configured
            audioQueue.push(mulawB64);
          } else {
            openaiWs.send(JSON.stringify({
              type:  "input_audio_buffer.append",
              audio: mulawB64,
            }));
          }
          break;
        }

        case "stop":
          log("[realtime:exotel] Call stopped", "ws");
          openaiWs?.close();
          break;

        case "dtmf":
          log(`[realtime:exotel] DTMF: ${JSON.stringify(payload)}`, "ws");
          break;

        default:
          log(`[realtime:exotel] unhandled event "${eventName}"`, "ws");
      }
    } catch (err: any) {
      log(`[realtime:exotel] handler error: ${err.message}`, "ws");
    }
  });

  exotelWs.on("close", () => {
    log("[realtime:exotel] Exotel disconnected — closing OpenAI session", "ws");
    openaiWs?.close();
  });

  exotelWs.on("error", (err) => {
    log(`[realtime:exotel] Exotel WS error: ${err.message}`, "ws");
  });
}

