     1→/**
     2→ * @module ConversationEvaluator
     3→ *
     4→ * Determines what the AI agent should do next given the current state.
     5→ *
     6→ * ## Purpose
     7→ * The evaluator is the decision-making layer above the state machine.  It
     8→ * reads the current `ConversationState` and returns an `AgentAction` — a
     9→ * pure recommendation with no side effects.  The caller (orchestrator) is
    10→ * responsible for acting on the recommendation.
    11→ *
    12→ * ## Hard gate: customer must respond before stage advances
    13→ * Stage advancement is ALWAYS blocked until `state.customerHasRespondedThisStage`
    14→ * is true.  This prevents the AI from racing through stages while talking to
    15→ * itself before the customer has said a single word.
    16→ *
    17→ * ## Design principle
    18→ * Pure function — no mutations, no I/O, no AI imports.
    19→ * `evaluate()` is deterministic given the same state.
    20→ */
    21→
    22→import { ConversationStage, STAGE_METADATA } from './ConversationStage.js';
    23→import type { ConversationState } from './ConversationState.js';
    24→
    25→// ─── Agent Action Types ───────────────────────────────────────────────────────
    26→
    27→export type AgentActionType =
    28→  | 'ASK_QUESTION'
    29→  | 'EXPLAIN'
    30→  | 'SUMMARIZE'
    31→  | 'HANDLE_OBJECTION'
    32→  | 'ATTEMPT_CLOSE'
    33→  | 'ADVANCE_STAGE'
    34→  | 'RE_ENGAGE'    // customer silent / disengaged
    35→  | 'WRAP_UP';     // call about to complete
    36→
    37→/**
    38→ * A structured recommendation produced by the evaluator.
    39→ */
    40→export interface AgentAction {
    41→  /** The recommended next action type. */
    42→  readonly action: AgentActionType;
    43→  /** Confidence level for this recommendation (0–1). */
    44→  readonly confidence: number;
    45→  /** Human-readable rationale for the recommendation. */
    46→  readonly rationale: string;
    47→  /** Whether the state machine should advance stage after this action. */
    48→  readonly shouldAdvanceStage: boolean;
    49→}
    50→
    51→// ─── Evaluation Config ────────────────────────────────────────────────────────
    52→
    53→export interface EvaluatorConfig {
    54→  /**
    55→   * Maximum questions to ask in a single stage before forcing an advance.
    56→   * @default 4
    57→   */
    58→  maxQuestionsPerStage: number;
    59→  /**
    60→   * Maximum milliseconds to spend in a single stage before forcing an advance.
    61→   * @default 120_000 (2 minutes)
    62→   */
    63→  maxMsPerStage: number;
    64→  /**
    65→   * Minimum pain points needed before PRESENTATION is allowed.
    66→   * @default 1
    67→   */
    68→  minPainPointsForPresentation: number;
    69→}
    70→
    71→export const DEFAULT_EVALUATOR_CONFIG: Readonly<EvaluatorConfig> = {
    72→  maxQuestionsPerStage: 4,
    73→  maxMsPerStage: 120_000,
    74→  minPainPointsForPresentation: 1,
    75→};
    76→
    77→// ─── ConversationEvaluator ────────────────────────────────────────────────────
    78→
    79→export class ConversationEvaluator {
    80→  private readonly config: Readonly<EvaluatorConfig>;
    81→
    82→  constructor(config: Partial<EvaluatorConfig> = {}) {
    83→    this.config = Object.freeze({ ...DEFAULT_EVALUATOR_CONFIG, ...config });
    84→  }
    85→
    86→  /**
    87→   * Evaluates the current conversation state and returns a recommended action.
    88→   * Pure — no mutations, no async.
    89→   *
    90→   * HARD RULE: No stage advancement is ever recommended unless the customer
    91→   * has spoken at least once in the current stage.
    92→   */
    93→  evaluate(state: ConversationState, now: number = Date.now()): AgentAction {
    94→    // ── Terminal — wrap up ────────────────────────────────────────────────────
    95→    if (state.isTerminal) {
    96→      return this._action('WRAP_UP', 1, 'Conversation is in a terminal stage.', false);
    97→    }
    98→
    99→    // ── Unresolved objection — must handle before anything else ───────────────
   100→    if (state.hasUnresolvedObjections && state.currentStage !== ConversationStage.OBJECTION_HANDLING) {
   101→      return this._action(
   102→        'HANDLE_OBJECTION',
   103→        0.95,
   104→        `There are ${state.memory.unresolvedObjections.length} unresolved objection(s). Transition to objection handling.`,
   105→        true
   106→      );
   107→    }
   108→
   109→    const timeInStage = state.timeInCurrentStage(now);
   110→    const questionsInStage = state.questionsInCurrentStage;
   111→
   112→    // ── Stage-specific evaluation ─────────────────────────────────────────────
   113→    switch (state.currentStage) {
   114→      case ConversationStage.GREETING:
   115→        return this._evaluateGreeting(state);
   116→
   117→      case ConversationStage.RAPPORT:
   118→        return this._evaluateRapport(state, timeInStage, questionsInStage);
   119→
   120→      case ConversationStage.DISCOVERY:
   121→        return this._evaluateDiscovery(state, questionsInStage);
   122→
   123→      case ConversationStage.QUALIFICATION:
   124→        return this._evaluateQualification(state, questionsInStage);
   125→
   126→      case ConversationStage.PRESENTATION:
   127→        return this._evaluatePresentation(state, questionsInStage);
   128→
   129→      case ConversationStage.OBJECTION_HANDLING:
   130→        return this._evaluateObjectionHandling(state);
   131→
   132→      case ConversationStage.CLOSING:
   133→        return this._evaluateClosing(state);
   134→
   135→      case ConversationStage.CALL_COMPLETED:
   136→        return this._action('WRAP_UP', 1, 'Call is complete.', false);
   137→    }
   138→
   139→    // Exhaustive default
   140→    return this._action('ASK_QUESTION', 0.5, 'Unknown stage — default to asking a question.', false);
   141→  }
   142→
   143→  // ─── Stage Evaluators ──────────────────────────────────────────────────────
   144→
   145→  private _evaluateGreeting(state: ConversationState): AgentAction {
   146→    if (state.turnsInCurrentStage === 0) {
   147→      return this._action('ASK_QUESTION', 1, 'No turns yet — open with greeting and ask permission to continue.', false);
   148→    }
   149→    // HARD GATE: customer must have responded before we advance
   150→    if (!state.customerHasRespondedThisStage) {
   151→      return this._action('ASK_QUESTION', 0.7, 'Waiting for customer to respond to greeting — do not advance yet.', false);
   152→    }
   153→    if (state.hasMetMinimumTurns) {
   154→      return this._action('ADVANCE_STAGE', 0.9, 'Greeting complete and customer has responded — advance to rapport.', true);
   155→    }
   156→    return this._action('ASK_QUESTION', 0.8, 'Continue greeting — minimum turns not yet met.', false);
   157→  }
   158→
   159→  private _evaluateRapport(
   160→    state: ConversationState,
   161→    timeInStage: number,
   162→    questionsInStage: number
   163→  ): AgentAction {
   164→    // HARD GATE: customer must have responded before we advance
   165→    if (!state.customerHasRespondedThisStage) {
   166→      return this._action('ASK_QUESTION', 0.9, 'Waiting for customer rapport response — do not advance yet.', false);
   167→    }
   168→    if (questionsInStage >= 2 || timeInStage > 45_000) {
   169→      return this._action('ADVANCE_STAGE', 0.85, 'Rapport established and customer has engaged — transition to discovery.', true);
   170→    }
   171→    return this._action('ASK_QUESTION', 0.9, 'Build rapport with an open question about the customer.', false);
   172→  }
   173→
   174→  private _evaluateDiscovery(
   175→    state: ConversationState,
   176→    questionsInStage: number
   177→  ): AgentAction {
   178→    const painPoints = state.memory.painPoints.length;
   179→    const atLimit = questionsInStage >= this.config.maxQuestionsPerStage;
   180→
   181→    // HARD GATE: customer must have responded before we advance
   182→    if (!state.customerHasRespondedThisStage) {
   183→      return this._action('ASK_QUESTION', 0.92, 'Waiting for customer discovery response — do not advance yet.', false);
   184→    }
   185→    if (painPoints >= this.config.minPainPointsForPresentation && state.hasMetMinimumTurns) {
   186→      return this._action('ADVANCE_STAGE', 0.88, `${painPoints} pain point(s) found — ready for qualification.`, true);
   187→    }
   188→    if (atLimit) {
   189→      return this._action(
   190→        'SUMMARIZE',
   191→        0.75,
   192→        'Question limit reached in discovery — summarise findings before advancing.',
   193→        true
   194→      );
   195→    }
   196→    return this._action('ASK_QUESTION', 0.92, 'Continue discovering pain points.', false);
   197→  }
   198→
   199→  private _evaluateQualification(
   200→    state: ConversationState,
   201→    questionsInStage: number
   202→  ): AgentAction {
   203→    const { budget, timeline, isDecisionMaker } = state.memory;
   204→    const qualified = budget !== undefined && timeline !== undefined && isDecisionMaker !== undefined;
   205→    const atLimit = questionsInStage >= this.config.maxQuestionsPerStage;
   206→
   207→    // HARD GATE: customer must have responded before we advance
   208→    if (!state.customerHasRespondedThisStage) {
   209→      return this._action('ASK_QUESTION', 0.95, 'Waiting for customer qualification response — do not advance yet.', false);
   210→    }
   211→    if (qualified) {
   212→      return this._action('ADVANCE_STAGE', 0.9, 'All qualification data gathered — advance to presentation.', true);
   213→    }
   214→    if (atLimit) {
   215→      return this._action(
   216→        'SUMMARIZE',
   217→        0.7,
   218→        'Question limit reached in qualification — advance with partial data.',
   219→        true
   220→      );
   221→    }
   222→    // Determine which field to qualify next
   223→    if (isDecisionMaker === undefined) {
   224→      return this._action('ASK_QUESTION', 0.95, 'Decision-maker not confirmed — ask about authority.', false);
   225→    }
   226→    if (budget === undefined) {
   227→      return this._action('ASK_QUESTION', 0.9, 'Budget not captured — ask about investment capacity.', false);
   228→    }
   229→    return this._action('ASK_QUESTION', 0.85, 'Timeline not captured — ask about urgency.', false);
   230→  }
   231→
   232→  private _evaluatePresentation(
   233→    state: ConversationState,
   234→    questionsInStage: number
   235→  ): AgentAction {
   236→    if (state.turnsInCurrentStage === 0) {
   237→      return this._action('EXPLAIN', 0.95, 'Present the solution tied to the discovered pain.', false);
   238→    }
   239→    // HARD GATE: customer must have responded before we advance
   240→    if (!state.customerHasRespondedThisStage) {
   241→      return this._action('ASK_QUESTION', 0.8, 'Waiting for customer reaction to presentation — do not advance yet.', false);
   242→    }
   243→    if (questionsInStage >= 1 && state.hasMetMinimumTurns) {
   244→      return this._action('ATTEMPT_CLOSE', 0.8, 'Presentation delivered and reaction gauged — attempt close.', true);
   245→    }
   246→    return this._action('ASK_QUESTION', 0.85, 'Check reaction to presentation with a probing question.', false);
   247→  }
   248→
   249→  private _evaluateObjectionHandling(state: ConversationState): AgentAction {
   250→    const unresolved = state.memory.unresolvedObjections;
   251→    if (unresolved.length === 0) {
   252→      return this._action('ADVANCE_STAGE', 0.9, 'All objections resolved — return to funnel.', true);
   253→    }
   254→    if (state.turnsInCurrentStage === 0) {
   255→      return this._action('EXPLAIN', 0.95, `Address objection: "${unresolved[0].topic}".`, false);
   256→    }
   257→    return this._action('ASK_QUESTION', 0.8, 'Check whether the objection has been resolved to the customer\'s satisfaction.', false);
   258→  }
   259→
   260→  private _evaluateClosing(state: ConversationState): AgentAction {
   261→    if (!state.memory.hasNextAction) {
   262→      return this._action('SUMMARIZE', 0.9, 'Summarise conversation and propose a concrete next step.', false);
   263→    }
   264→    if (state.memory.commitments.length > 0) {
   265→      return this._action('WRAP_UP', 0.95, 'Commitment made and next action confirmed — wrap up gracefully.', true);
   266→    }
   267→    return this._action('ATTEMPT_CLOSE', 0.85, 'Next action set but commitment not yet confirmed — solidify.', false);
   268→  }
   269→
   270→  // ─── Helpers ────────────────────────────────────────────────────────────────
   271→
   272→  private _action(
   273→    action: AgentActionType,
   274→    confidence: number,
   275→    rationale: string,
   276→    shouldAdvanceStage: boolean
   277→  ): AgentAction {
   278→    return Object.freeze({ action, confidence, rationale, shouldAdvanceStage });
   279→  }
   280→}
