    96→
    97→  // ── DO NOT ASK AGAIN block ──────────────────────────────────────────────────
    98→  const doNotAskLines: string[] = [];
    99→  if (mem.customerName) doNotAskLines.push(`  • Their name (it's ${mem.customerName})`);
   100→  if (mem.company) doNotAskLines.push(`  • Their company (it's ${mem.company})`);
   101→  if (mem.intent) doNotAskLines.push(`  • Their intent (already stated)`);
   102→  if (mem.painPoints.length > 0) {
   103→    mem.painPoints.forEach((p) => doNotAskLines.push(`  • Pain point already given: "${p}"`));
   104→  }
   105→  if (mem.budget) doNotAskLines.push(`  • Their budget (it's ${mem.budget})`);
   106→  if (mem.timeline) doNotAskLines.push(`  • Their timeline (it's ${mem.timeline})`);
   107→  if (mem.isDecisionMaker !== undefined) {
   108→    doNotAskLines.push(
   109→      `  • Whether they're the decision-maker (answer: ${mem.isDecisionMaker ? 'Yes' : 'No'})`
   110→    );
   111→  }
   112→  const doNotAskSection =
   113→    doNotAskLines.length > 0
   114→      ? `⛔ DO NOT ASK AGAIN — the caller already provided:\n${doNotAskLines.join('\n')}`
   115→      : '  (no facts captured yet — nothing to guard)';
   116→
   117→  // ── Objections ──────────────────────────────────────────────────────────────
   118→  const unresolvedObjLines = mem.unresolvedObjections.map(
   119→    (o) => `  • [UNRESOLVED] ${o.topic}${o.verbatim ? ` — "${o.verbatim}"` : ''}`
   120→  );
   121→  const resolvedObjLines = mem.objections
   122→    .filter((o) => o.resolved)
   123→    .map((o) => `  • [resolved]   ${o.topic}`);
   124→  const objSection =
   125→    [...unresolvedObjLines, ...resolvedObjLines].join('\n') ||
   126→    '  none';
   127→
   128→  // ── Commitments ─────────────────────────────────────────────────────────────
   129→  const commitSection =
   130→    mem.commitments.length > 0
