   132→      : '  none';
   133→
   134→  // ── Next action ─────────────────────────────────────────────────────────────
   135→  const nextAction = mem.nextAction ?? 'not yet determined';
   136→
   137→  // ── Progress ────────────────────────────────────────────────────────────────
