   142→  const customerHasResponded = state.customerHasRespondedThisStage;
   143→
   144→  // ── Build section ───────────────────────────────────────────────────────────
   145→  return [
   146→    `\n${bar}`,
   147→    `## LIVE CONVERSATION STATE  [updated ${ts}]`,
   148→    bar,
   149→    `Current Stage:         ${stageLabel}`,
   150→    `Previous Stage:        ${prevLabel}`,
   151→    `Stage History:         ${historyStr}`,
   152→    `Time in Stage:         ${timeInStage}s`,
   153→    `Agent Turns:           ${turnsTotal} total, ${turnsStage} this stage`,
   154→    `Customer Turns:        ${customerTurnsStage} this stage`,
   155→    `Customer Responded:    ${customerHasResponded ? 'YES — customer has spoken this stage' : 'NO — customer has NOT spoken yet this stage'}`,
   156→    `Questions Asked:       ${questionsStage} this stage`,
   157→    `Min Turns Met:         ${state.hasMetMinimumTurns ? 'Yes' : 'No'}`,
   158→    ``,
   159→    `Known Customer Facts:`,
   160→    knownFacts,
   161→    ``,
   162→    doNotAskSection,
   163→    ``,
   164→    `Objections:`,
   165→    objSection,
   166→    ``,
   167→    `Commitments:`,
   168→    commitSection,
   169→    ``,
