   202→      return [
   203→        `Say: "Hi${nameFragment}! This is ${ctx.agentName} from ${ctx.companyName}.`,
   204→        `Is this a good time for a quick call?"`,
   205→        `Then STOP immediately. Do not say another word.`,
   206→        `Wait for the caller to answer — DO NOT generate their reply.`,
   207→      ].join(' ');
