   220→    // ── DISCOVERY ─────────────────────────────────────────────────────────────
   221→    // Rule: ask campaign-specific open questions to uncover real pain points.
   222→    case ConversationStage.DISCOVERY: {
   223→      if (mem.painPoints.length === 0) {
