   242→    // Rule: one qualifying question at a time — confirm authority, budget, timeline.
   243→    case ConversationStage.QUALIFICATION: {
   244→      const missingQuestions: string[] = [];
   245→      if (mem.isDecisionMaker === undefined)
   246→        missingQuestions.push(`"Are you the right person to decide on something like this, or would others be involved?"`);
   247→      if (!mem.budget)
   248→        missingQuestions.push(`"Do you have a budget in mind for solving this?"`);
   249→      if (!mem.timeline)
   250→        missingQuestions.push(`"What's your timeline — is this something you're looking to solve soon?"`);
