   257→        missingQuestions[0],
   258→        `After asking — STOP and wait for ${callerName} to answer.`,
   259→        `Do not ask multiple questions at once.`,
   260→      ].join(' ');
   261→    }
   262→
   263→    // ── PRESENTATION ──────────────────────────────────────────────────────────
   264→    // Rule: tie the product directly to their stated pain — one capability, not a feature list.
   265→    case ConversationStage.PRESENTATION: {
   266→      const topPain = mem.painPoints[0] ?? 'their stated challenge';
   267→      return [
   268→        `Present ${product} as the direct answer to: "${topPain}".`,
   269→        `ONE sentence: what it does — then link it to exactly what ${callerName} told you.`,
   270→        `Do NOT list features. Connect ONE capability to their specific pain.`,
   271→        `Then ask a confirming question: "Does that sound like it would help you?"`,
   272→        `— then STOP and wait for their reaction.`,
