   414→    if (isMuted) return;
   415→
   416→    this._provider.sendAudio(base64);
   417→    // Client VAD — only runs while actively listening for caller speech
   418→    if (this._vadState === 'listening' || this._vadState === 'in_speech') {
   419→      this._processClientVAD(base64);
   420→    }
