   425→  private _processClientVAD(base64: string): void {
   426→    const pcm = Buffer.from(base64, 'base64');
   427→    const sampleCount = Math.floor(pcm.length / 2);
   428→    if (sampleCount === 0) return;
   429→
   430→    // RMS energy
   431→    let sum = 0;
   432→    for (let i = 0; i < sampleCount; i++) {
   433→      const s = pcm.readInt16LE(i * 2);
   434→      sum += s * s;
   435→    }
   436→    const rms = Math.sqrt(sum / sampleCount);
   437→
   438→    // Chunk duration in ms at 24 kHz PCM16
   439→    const chunkMs = Math.round((sampleCount / 24000) * 1000);
   440→    const isSpeech = rms >= RealtimeBridge.VAD_SPEECH_RMS;
   441→
   442→    if (this._vadState === 'listening') {
   443→      if (isSpeech) {
   444→        this._vadState    = 'in_speech';
   445→        this._vadSpeechMs = chunkMs;
   446→        this._vadSilenceMs = 0;
   447→        console.log(`[ClientVAD] Speech detected  rms=${Math.round(rms)}  sessionId=${this._sessionId}`);
   448→      }
   449→      return;
   450→    }
   451→
   452→    // _vadState === 'in_speech'
   453→    if (isSpeech) {
   454→      this._vadSpeechMs  += chunkMs;
   455→      this._vadSilenceMs  = 0;
   456→      if (this._vadSpeechMs >= RealtimeBridge.VAD_MAX_TURN_MS) {
   457→        this._commitTurn('max_turn_duration');
   458→      }
   459→    } else {
   460→      this._vadSilenceMs += chunkMs;
   461→      if (this._vadSilenceMs >= RealtimeBridge.VAD_SILENCE_MS) {
   462→        if (this._vadSpeechMs >= RealtimeBridge.VAD_MIN_SPEECH_MS) {
   463→          this._commitTurn('silence_after_speech');
   464→        } else {
   465→          // Noise burst — too short, reset to listening
   466→          this._vadState     = 'listening';
   467→          this._vadSpeechMs  = 0;
   468→          this._vadSilenceMs = 0;
   469→        }
   470→      }
   471→    }
   472→  }
