   507→  private _toAudioMime(format: string): 'audio/pcm' | 'audio/pcmu' | 'audio/pcma' {
   508→    switch (format) {
   509→      case 'g711_ulaw': return 'audio/pcmu';
   510→      case 'g711_alaw': return 'audio/pcma';
   511→      case 'pcm16':     return 'audio/pcm';
   512→      default:          return 'audio/pcm';
   513→    }
   514→  }
