   519→   * Controlled ONLY by the `VOICE_OUTPUT_FORMAT` env var:
   520→   *   - 'pcmu' (default): request G.711 μ-law from OpenAI — passed straight
   521→   *     through to Exotel by ExotelAdapter, unchanged from prior behaviour.
   522→   *   - 'pcm': request raw 16-bit PCM from OpenAI — ExotelAdapter converts it
   523→   *     to G.711 μ-law before sending to Exotel.
   524→   * Any other/unset value falls back to the existing configured default.
   525→   */
   526→  private _resolveOutputAudioMime(): 'audio/pcm' | 'audio/pcmu' | 'audio/pcma' {
   527→    const mode = (process.env['VOICE_OUTPUT_FORMAT'] || 'pcmu').toLowerCase();
   528→    if (mode === 'pcm')  return 'audio/pcm';
   529→    if (mode === 'pcmu') return 'audio/pcmu';
   530→    return this._toAudioMime(this._config.outputAudioFormat);
