   533→  private _buildSessionConfig(instructions: string): Partial<RealtimeSessionResource> {
   534→    return {
   535→      type: 'realtime',
   536→      instructions,
   537→      // Cap each AI response to ~250 tokens (≈ 3-4 short sentences).
   538→      // Without this limit the model can generate an unlimited-length response
   539→      // and talk through multiple conversation turns in one shot — asking a
   540→      // question AND producing a hypothetical customer answer AND responding
   541→      // to that answer, all in a single audio clip.  250 tokens is generous
   542→      // enough for a complete sales response while preventing runaway monologues.
   543→      max_output_tokens: 250,
   544→      // turn_detection is nested under audio.input — this is the only accepted
   545→      // placement for gpt-realtime.  Top-level 'session.turn_detection' is
   546→      // rejected as unknown_parameter, which also prevents session.updated from
   547→      // firing and silences the greeting entirely.
   548→      //
   549→      // threshold=0.2  — below default 0.5; Exotel resampled 8→24 kHz audio
   550→      //                   has lower amplitude characteristics
   551→      // silence_duration_ms=600 — slightly longer than default (200ms) so the
   552→      //                   VAD doesn't cut the caller off mid-sentence on a phone
   553→      // create_response=true   — server VAD auto-commits AND creates a response
   554→      // interrupt_response=true — server VAD handles barge-in automatically
   555→      //
   556→      // RealtimeBridge adds an 8 s timeout fallback: if server VAD does not
   557→      // fire within 8 s of the AI finishing, the buffer is committed and a
   558→      // response is created.  This prevents silence when server VAD misses a
   559→      // caller turn.  Energy-based client VAD (VAD_SPEECH_RMS=15000) is kept
   560→      // but effectively disabled for phone noise.
   561→      audio: {
   562→        input: {
   563→          // rate is required by the API — omitting it causes missing_required_parameter error.
   564→          format: { type: 'audio/pcm' as const, rate: 24000 },
   565→          transcription: this._config.enableInputTranscription
   566→            ? { model: this._config.transcriptionModel }
   567→            : null,
   568→          turn_detection: {
