   570→            threshold: 0.2,
   571→            prefix_padding_ms: 300,
   572→            silence_duration_ms: 1500,
   573→            create_response: true,
   574→            interrupt_response: true,
   575→          },
   576→        },
   577→        output: {
   578→          format: { type: this._resolveOutputAudioMime(), rate: 24000 },
   579→          voice: this._config.voice,
   580→        },
   581→      },
   582→    };
   583→  }
