   237→   * When the payload is a `Uint8Array`, converts via Buffer.
   238→   */
   239→  private _toBase64(payload: Uint8Array | string): string {
   240→    if (typeof payload === 'string') return payload;
   241→    return Buffer.from(payload).toString('base64');
   242→  }
