   246→   * `AudioEncoding`. Falls back to `'mulaw'` for unrecognised encodings.
   247→   */
   248→  private _resolveEncoding(raw: string): 'pcm' | 'pcm16' | 'linear16' | 'mulaw' | 'alaw' | 'opus' {
   249→    const known = new Set(['pcm', 'pcm16', 'linear16', 'mulaw', 'alaw', 'opus']);
   250→    return known.has(raw)
   251→      ? (raw as 'pcm' | 'pcm16' | 'linear16' | 'mulaw' | 'alaw' | 'opus')
