     1→/**
     2→ * @module PcmMulawCodec
     3→ *
     4→ * Pure TypeScript G.711 μ-law encoder. No third-party codec libraries.
     5→ *
     6→ * ## Why this exists
     7→ * When `VOICE_OUTPUT_FORMAT=pcm`, OpenAI is configured to emit raw 16-bit
     8→ * PCM (8 kHz mono) instead of μ-law. Exotel's media WebSocket only accepts
     9→ * G.711 μ-law payloads, so this module converts PCM → μ-law immediately
    10→ * before the frame is handed to Exotel.
    11→ *
    12→ * ## Algorithm
    13→ * Standard ITU-T G.711 μ-law compression:
    14→ *   1. Extract sign, take absolute value.
    15→ *   2. Clip to the standard 32635 ceiling.
    16→ *   3. Add the standard bias (0x84 / 132).
    17→ *   4. Find the exponent (segment) by locating the highest set bit.
    18→ *   5. Extract a 4-bit mantissa from the segment.
    19→ *   6. Pack sign|exponent|mantissa and bitwise-invert (μ-law convention).
    20→ *
    21→ * This is the encode half of the μ-law codec; it is independent of, and
    22→ * does not replace, any other codec used elsewhere in the codebase.
    23→ */
    24→
    25→/**
    26→ * Downsample a Buffer of 16-bit little-endian PCM samples from `srcRate` to
    27→ * `dstRate` using linear interpolation.
    28→ *
    29→ * Works cleanly for integer-ratio pairs (e.g. 24000→8000, 3:1).
    30→ * Input and output are raw PCM16 LE Buffers (2 bytes per sample).
    31→ */
    32→export function resamplePCM16(pcm: Buffer, srcRate: number, dstRate: number): Buffer {
    33→  if (srcRate === dstRate) return pcm;
    34→  const sampleCount = Math.floor(pcm.length / 2);
    35→  const samples = new Int16Array(sampleCount);
    36→  for (let i = 0; i < sampleCount; i++) {
    37→    samples[i] = pcm.readInt16LE(i * 2);
    38→  }
    39→  const ratio = srcRate / dstRate;
    40→  const outLength = Math.floor(sampleCount / ratio);
    41→  const out = Buffer.allocUnsafe(outLength * 2);
    42→  for (let i = 0; i < outLength; i++) {
    43→    const pos  = i * ratio;
    44→    const lo   = Math.floor(pos);
    45→    const hi   = Math.min(lo + 1, sampleCount - 1);
    46→    const frac = pos - lo;
    47→    const s    = Math.round(samples[lo] * (1 - frac) + samples[hi] * frac);
    48→    out.writeInt16LE(s, i * 2);
    49→  }
    50→  return out;
    51→}
    52→
    53→const MULAW_BIAS = 0x84; // 132 — standard G.711 μ-law bias
    54→const MULAW_CLIP = 32635; // standard G.711 μ-law clip ceiling
    55→
    56→/**
    57→ * Encodes a single signed 16-bit PCM sample (range -32768..32767) to one
    58→ * G.711 μ-law byte (range 0x00..0xFF).
    59→ */
    60→export function encodeMulawSample(sample: number): number {
    61→  let sign = 0;
    62→
    63→  if (sample < 0) {
    64→    sign = 0x80;
    65→    sample = -sample;
    66→  }
    67→  if (sample > MULAW_CLIP) sample = MULAW_CLIP;
    68→
    69→  sample += MULAW_BIAS;
    70→
    71→  let exponent = 7;
    72→  for (let mask = 0x4000; (sample & mask) === 0 && exponent > 0; mask >>= 1) {
    73→    exponent--;
    74→  }
    75→
    76→  const mantissa = (sample >> (exponent + 3)) & 0x0f;
    77→  return ~(sign | (exponent << 4) | mantissa) & 0xff;
    78→}
    79→
    80→/**
    81→ * Decodes a buffer of G.711 μ-law bytes (as received from Exotel) into a
    82→ * buffer of raw 16-bit little-endian PCM samples — two output bytes per
    83→ * input byte.
    84→ *
    85→ * Standard ITU-T G.711 μ-law expansion:
    86→ *   1. Complement all bits (μ-law convention stores inverted bits).
    87→ *   2. Extract sign, 3-bit exponent, and 4-bit mantissa.
    88→ *   3. Reconstruct the linear PCM value and restore the sign.
    89→ */
    90→export function mulawToPcm16(mulaw: Buffer): Buffer {
    91→  const out = Buffer.allocUnsafe(mulaw.length * 2);
    92→  for (let i = 0; i < mulaw.length; i++) {
    93→    const byte     = ~mulaw[i] & 0xff;
    94→    const sign     = byte & 0x80;
    95→    const exponent = (byte >> 4) & 0x07;
    96→    const mantissa = byte & 0x0f;
    97→    let sample     = ((mantissa << 1) + 33) << exponent;
    98→    sample        -= 33;
    99→    const s16 = sign ? -sample : sample;
   100→    out.writeInt16LE(Math.max(-32768, Math.min(32767, s16)), i * 2);
   101→  }
   102→  return out;
   103→}
   104→
   105→/**
   106→ * Converts a buffer of raw 16-bit little-endian PCM samples (as emitted by
   107→ * OpenAI in `audio/pcm` mode) into a buffer of G.711 μ-law bytes — one
   108→ * output byte per input sample.
   109→ *
   110→ * If the input length is odd (a stray trailing half-sample), that trailing
   111→ * byte is dropped rather than guessed at.
   112→ */
   113→export function pcm16ToMulaw(pcm: Buffer): Buffer {
   114→  const sampleCount = Math.floor(pcm.length / 2);
   115→  const out = Buffer.allocUnsafe(sampleCount);
   116→
   117→  for (let i = 0; i < sampleCount; i++) {
   118→    const sample = pcm.readInt16LE(i * 2);
   119→    out[i] = encodeMulawSample(sample);
   120→  }
   121→
   122→  return out;
   123→}
